	@RequestMapping(value = "/ajax", method = RequestMethod.GET)
	public String memberList(@RequestParamMap ParamMap param, Model model) throws Exception{
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getMemberList(param));
		return JSON_VIEW;
	}

	/**
	 * 가입현황(LGC) 조회
	 */
	@Operation(summary = "가입현황 통계", description = "가입현황 통계 정보를 조회합니다.")
	@RequestMapping(value = "/total", method = RequestMethod.GET)
	public String getMemberTotalCount(@RequestParamMap ParamMap param, Model model) {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getMemberTotalInfo(param));
		return JSON_VIEW;
	}

	/**
	 * 가입자 등록
	 */
	@Operation(summary = "가입자 등록", description = "새 가입자를 등록합니다.")
	@Parameters({
		@Parameter(name = "ctn", description = "전화번호", example = "01012345678", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "os", description = "OS (0: Android)", example = "0", schema = @Schema(type = "string")),
		@Parameter(name = "exceptionPolicy", description = "예외정책 (0: 일반, 1: VIP, 2: 예외1, 3: 예외2, 4: 예외3)", example = "0", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "managerName", description = "담당자명", example = "홍길동", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "corporationYn", description = "법인여부 (1: 법인, 0: 개인)", example = "1", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "immediately", description = "즉시 가입 여부", example = "true", required = true, schema = @Schema(type = "boolean")),
		@Parameter(name = "testUserYn", description = "테스트 사용자 여부 (Y/N)", example = "N", schema = @Schema(type = "string")),
		@Parameter(name = "banSolns", description = "차단 솔루션 목록 (콤마 구분)", example = "1,2,3", schema = @Schema(type = "string")),
		@Parameter(name = "noteLen", description = "메모 개수", example = "2", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "notes[0]", description = "메모1", example = "첫번째 메모입니다", schema = @Schema(type = "string")),
		@Parameter(name = "notes[1]", description = "메모2", example = "두번째 메모입니다", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createMember(@RequestParamMap(requiredValues= {"ctn", "exceptionPolicy","managerName","corporationYn","immediately"}) ParamMap param, 
			@Parameter(description = "개인정보 활용동의서 이미지 파일") @RequestParam (value="consentFormImg", required=false) MultipartFile consentFormImg, Model model) throws Exception{
		int maxSize5MB = 1024 * 1024 * 5;

		if (CommonUtil.isVulnerability(new String[] {"managerName"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}

		if (!CommonUtil.isNum(param.getString("noteLen"))) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		for (int i = 0; i < param.getInt("noteLen"); i++) {
			if (CommonUtil.isVulnerability(new String[] {"notes["+i+"]"}, param)) {
				throw new LogicException("VULNERABLE_VALUE", "002");
			}
		}

		//개인정보활용동의서
		if (consentFormImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(consentFormImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < consentFormImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}

		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.createMember(param, consentFormImg));
		return JSON_VIEW;
	}

	/**
	 * 엑셀 등록
	 */
	@Operation(summary = "가입자 엑셀 업로드", description = "엑셀 파일로 가입자를 일괄 등록합니다.")
	@RequestMapping(value = "/excel", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createMemberExcelUpload(@RequestParamMap ParamMap param, Model model
			, @Parameter(name = "memberExcelFile", description = "가입자 등록 엑셀파일")@RequestPart("memberExcelFile") MultipartFile memberExcelFile) throws LogicException {
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		if (!CommonUtil.excelFileExtCheck(CommonUtil.getFileExt(memberExcelFile.getOriginalFilename()))){
			throw new LogicException("VALIDATION_FAIL","003");
		}
		model.addAllAttributes(service.createMemberExcelUpload(param, memberExcelFile));
		return JSON_VIEW;
	}

	/**
	 * 엑셀 업로드 완료 여부 체크
	 */
	@Operation(summary = "엑셀 업로드 상태 확인", description = "엑셀 업로드 완료 여부를 확인합니다.")
	@RequestMapping(value = "/excel/upload/check", method = RequestMethod.GET)
	public String checkExcelUpload(@RequestParamMap ParamMap param, Model model) {
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.checkExcelUpload(param));
		return JSON_VIEW;
	}

	/**
	 * 상세조회
	 */
	@Operation(summary = "가입자 상세 조회", description = "특정 가입자의 상세 정보를 조회합니다.")
	@Parameters({
		@Parameter(name = "memberSeq", description = "가입자 시퀀스", example = "1", in = ParameterIn.PATH, schema = @Schema(type = "integer", format = "int64"))
	})
	@History(historyType = HistoryType.PERSONAL_INFO_ACCESS, reqType = "update_user", checkCorporation = true)
	@RequestMapping(value = "/{memberSeq}", method = RequestMethod.GET)
	public String getMember(
			@PathVariable("memberSeq") long memberSeq, 
			@RequestParamMap ParamMap param, Model model) throws LogicException{
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		param.put("memberSeq", memberSeq);
		try {
			model.addAllAttributes(service.getMember(param));
		} catch (Exception e) {
			throw new LogicException("MEMBER NOT FOUND");
		}
		return JSON_VIEW;
