		@Parameter(name = "os", description = "OS (0:Android)", example = "0", schema = @Schema(type = "string")),
		@Parameter(name = "exceptionPolicy", description = "예외정책 (0:일반, 1:VIP, 2:예외1, 3:예외2, 4:예외3)", example = "0", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "managerName", description = "담당자명", example = "홍길동", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "corporationYn", description = "법인여부 (1:법인, 0:개인)", example = "0", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "testUserYn", description = "테스트 사용자 여부 (Y/N)", example = "N", schema = @Schema(type = "string")),
		@Parameter(name = "banSolns", description = "차단 솔루션 목록", example = "11,12,13,14", schema = @Schema(type = "string")),
		@Parameter(name = "noteLen", description = "메모 개수", example = "1", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "notes[0]", description = "메모1", example = "메모입니다", schema = @Schema(type = "string")),
		@Parameter(name = "notes[1]", description = "메모2", schema = @Schema(type = "string")),
		@Parameter(name = "existingConsentFormUrl", description = "기존 개인정보 활용동의 url", schema = @Schema(type = "string")),
		@Parameter(name = "existingTestUserYn", description = "기존 테스트 사용자 여부 (Y/N)", example = "N", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "/{memberSeq}", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String modifyMember(
			@PathVariable("memberSeq") long memberSeq,
			@RequestParamMap(requiredValues={"ctn","exceptionPolicy", "managerName", "corporationYn"}) ParamMap param, 
			@Parameter(name = "consentFormImg", description = "개인정보 활용동의서 이미지 파일")@RequestPart (value="consentFormImg", required=false) MultipartFile consentFormImg, Model model) throws LogicException {

		int maxSize5MB = 1024 * 1024 * 5;

		if (CommonUtil.isVulnerability(new String[] {"managerName"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		if (!CommonUtil.isNum(param.getString("noteLen"))) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		for (int i = 0; i < param.getInt("noteLen"); i++) {
			if (CommonUtil.isVulnerability(new String[] {"notes["+i+"]"}, param)) {
				throw new LogicException("VULNERABLE_VALUE", "002");
			}
		}

		//개인정보활용동의서
		String existingTestUserYn = param.getString("existingTestUserYn");
		if (consentFormImg != null && (!CommonUtil.isNull(existingTestUserYn) && "N".equals(existingTestUserYn))) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(consentFormImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < consentFormImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}

		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		param.put("memberSeq", memberSeq);
		model.addAllAttributes(service.modifyMember(param, consentFormImg));
		return JSON_VIEW;
	}

