import org.springframework.web.multipart.MultipartFile;

@Tag(name = "Quota", description = "데이터 할당 관리 API")
@Controller
@RequestMapping("/web/admin/quota")
public class QuotaController extends CommonController {
    @Autowired
    private QuotaService service;

    private static String CLIENT_SEQ = "clientSeq";
    private static String LOGIN_CLIENT_SEQ = "loginClientSeq";
    @Operation(summary = "데이터 정보 화면", description = "데이터 할당 정보 화면을 조회합니다.")
    @RequestMapping(value = "", method = RequestMethod.GET)
    public String quotaInfoView(@RequestParamMap ParamMap param, Model model) {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        model.addAllAttributes(service.getSummary(param));
        return "admin/quota/infoView";
    }

    // region members

    @Operation(summary = "가입자 데이터 현황 화면", description = "가입자 데이터 현황 화면을 조회합니다.")
    @Parameters({
        @Parameter(name = "memberGroupSeq", description = "가입자 그룹 시퀀스", example = "1", schema = @Schema(type = "string"))
    })
    @RequestMapping(value = "members", method = RequestMethod.GET)
    public String memberListView(@RequestParamMap ParamMap param, Model model) throws LogicException {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        if (CommonUtil.isVulnerability(new String[]{"memberGroupSeq"}, param)) {
            throw new LogicException("VULNERABLE_VALUE", "002");
        }
        model.addAllAttributes(service.getGroupInfo(param));
        return "admin/quota/memberList";
    }

    @Operation(summary = "가입자 데이터 현황 조회", description = "페이징 처리된 가입자 데이터 현황을 조회합니다.")
    @Parameters({
        @Parameter(name = "searchType", description = "검색 유형(MANAGER_NAME: 사용자, CTN: 전화번호, GROUP_NAME: 그룹명, NOTE: 비고)", example = "CTN", schema = @Schema(type = "string", allowableValues = {"MANAGER_NAME", "CTN", "GROUP_NAME", "NOTE"})),
        @Parameter(name = "searchValue", description = "검색어", example = "", schema = @Schema(type = "string")),
        @Parameter(name = "memberGroupSeq", description = "가입자 그룹 시퀀스", example = "1", schema = @Schema(type = "string")),
        @Parameter(name = "start", description = "페이징 시작 위치", example = "0", schema = @Schema(type = "integer")),
        @Parameter(name = "length", description = "페이지 당 건수", example = "10", schema = @Schema(type = "integer")),
        @Parameter(name = "order[0][column]", description = "정렬 대상 컬럼 인덱스", example = "4", schema = @Schema(type = "integer")),
        @Parameter(name = "order[0][dir]", description = "정렬 방향", example = "asc", schema = @Schema(type = "string", allowableValues = {"asc", "desc"})),
        @Parameter(name = "columns[4][data]", description = "그룹명 컬럼 데이터 필드명", example = "groupName", schema = @Schema(type = "string")),
        @Parameter(name = "columns[5][data]", description = "할당량 컬럼 데이터 필드명", example = "quota", schema = @Schema(type = "string")),
        @Parameter(name = "columns[6][data]", description = "잔여량 컬럼 데이터 필드명", example = "remaining", schema = @Schema(type = "string")),
        @Parameter(name = "columns[7][data]", description = "그룹 가입일 컬럼 데이터 필드명", example = "memberGroupJoinedDate", schema = @Schema(type = "string"))
    })
	@History(historyType = HistoryType.PERSONAL_INFO_ACCESS, reqType = "quota_member_status")
    @RequestMapping(value = "members/ajax", method = RequestMethod.GET)
    public String memberList(@RequestParamMap ParamMap param, Model model) throws Exception {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        if (CommonUtil.isVulnerability(new String[]{"memberGroupSeq"}, param)) {
            throw new LogicException("VULNERABLE_VALUE", "002");
        }
        model.addAllAttributes(service.getMemberList(param));
        return JSON_VIEW;
    }


    @Operation(summary = "가입자 그룹 엑셀 등록 화면", description = "가입자 그룹 엑셀 업로드 화면을 조회합니다.")
    @RequestMapping(value = "members/excel", method = RequestMethod.GET)
    public String createMemberExcelView(@RequestParamMap ParamMap param, Model model) {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        return "admin/quota/memberExcel";
    }

    @Operation(summary = "가입자 그룹 엑셀 등록", description = "엑셀 파일을 업로드하여 가입자 그룹을 일괄 등록합니다.")
    @RequestMapping(value = "members/excel", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public String upsertMemberGroupExcelView(@RequestParamMap ParamMap param
            , @Parameter(description = "엑셀 파일") @RequestParam("excelFile") MultipartFile excelFile
            , Model model) throws LogicException {

        if (!CommonUtil.excelFileExtCheck(CommonUtil.getFileExt(excelFile.getOriginalFilename()))) {
            throw new LogicException("VALIDATION_FAIL", "003");
        }
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        model.addAllAttributes(service.updateMemberGroupsFromExcel(param, excelFile));
        return JSON_VIEW;
    }

    @Operation(summary = "가입자 샘플 파일 다운로드", description = "가입자 그룹 엑셀 업로드용 샘플 파일을 다운로드합니다.")
    @RequestMapping(value = "members/sample", method = RequestMethod.GET)
    public String downloadMemberExcelSample(@RequestParamMap ParamMap param, Model model) {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        model.addAllAttributes(service.downloadMemberExcelSample(param));
        return DOWN_VIEW;
